import { tier, governor, dispose } from '@chaff/tier';
const currentTier = tier();
if (currentTier === 'poster') {
  return <StaticPoster />;
}
const gov = governor({ level: currentTier, maxPixelRatio: 1.5 });
const controller = gov.attach(canvas, (delta) => {
  renderer.render(scene, camera);
});
return () => { controller.detach(); dispose(scene); };
